use serde_json::Value;
use t3_client::thread_views::{
    composer::{
        editor::{BuildOptions, build_document, serialize_document},
        structure,
    },
    document::Selection,
};
fn canonical(node: &mut Value) {
    if node["type"] == "orderedList"
        && node["attrs"]["type"].is_null()
        && let Some(attrs) = node["attrs"].as_object_mut()
    {
        attrs.remove("type");
    }
    if let Some(content) = node.get_mut("content").and_then(Value::as_array_mut) {
        let mut merged: Vec<Value> = Vec::new();
        for mut child in std::mem::take(content) {
            canonical(&mut child);
            if child["type"] == "text"
                && merged.last().is_some_and(|prior| {
                    prior["type"] == "text" && prior["marks"] == child["marks"]
                })
            {
                let prior = merged.last_mut().expect("valid fixture");
                prior["text"] = format!(
                    "{}{}",
                    prior["text"].as_str().expect("valid fixture"),
                    child["text"].as_str().expect("valid fixture")
                )
                .into();
            } else {
                merged.push(child);
            }
        }
        *content = merged;
    }
    if let Some(fields) = node.as_object_mut() {
        fields.retain(|key, value| {
            !(matches!(key.as_str(), "content" | "marks")
                && value.as_array().is_some_and(Vec::is_empty))
                && !(key == "attrs" && value.as_object().is_some_and(serde_json::Map::is_empty))
        });
    }
}
#[test]
fn boundary_keys_match_original_editor_structure_and_caret() {
    let cases: Value = serde_json::from_str(GOLDENS).expect("valid fixture");
    let mut failures = Vec::new();
    for case in cases.as_array().expect("valid fixture") {
        let source = case["text"].as_str().expect("valid fixture");
        let doc = build_document(source, BuildOptions::default(), |_| None, |_, _| false);
        let selection = Selection::caret(case["caret"].as_u64().expect("valid fixture") as usize);
        let result = if case["key"] == "Backspace" {
            structure::backspace(&doc, selection)
        } else {
            structure::delete(&doc, selection)
        };
        let handled = result.is_some();
        let (actual, caret) = result.map_or((doc, selection), |rewrite| {
            (rewrite.document, rewrite.selection)
        });
        let value = serialize_document(&actual).value;
        let mut actual_tree = actual;
        let mut expected_tree = case["tree"].clone();
        canonical(&mut actual_tree);
        canonical(&mut expected_tree);
        if actual_tree != expected_tree {
            failures.push(format!(
                "{source:?} {} @{}: tree {actual_tree} != {expected_tree}",
                case["key"], selection.head
            ));
        }
        if handled != case["handled"].as_bool().expect("valid fixture")
            || value != case["value"].as_str().expect("valid fixture")
            || caret.head != case["selection"].as_u64().expect("valid fixture") as usize
        {
            failures.push(format!(
                "{source:?} {} @{}: handled {handled}, value {value:?}, caret {} != {} {} {}",
                case["key"],
                selection.head,
                caret.head,
                case["handled"],
                case["value"],
                case["selection"]
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
