#[test]
fn enter_splits_lifts_and_exits_code_like_the_original_editor() {
    let cases: Value = serde_json::from_str(ENTER_GOLDENS).unwrap();
    let mut failures = Vec::new();
    for case in cases.as_array().unwrap() {
        let source = case["text"].as_str().unwrap();
        let doc = build_document(source, BuildOptions::default(), |_| None, |_, _| false);
        let selection = Selection::caret(case["caret"].as_u64().unwrap() as usize);
        let result = structure::enter(&doc, selection);
        let handled = result.is_some();
        let (mut tree, caret) = result.map_or((doc, selection), |rewrite| {
            (rewrite.document, rewrite.selection)
        });
        let value = serialize_document(&tree).value;
        let mut expected = case["tree"].clone();
        canonical(&mut tree);
        canonical(&mut expected);
        if handled != case["handled"].as_bool().unwrap()
            || value != case["value"].as_str().unwrap()
            || caret.head != case["selection"].as_u64().unwrap() as usize
            || tree != expected
        {
            failures.push(format!("{source:?} @{}: handled {handled}, value {value:?}, caret {} != {} {} {}; tree {tree} != {expected}",selection.head,caret.head,case["handled"],case["value"],case["selection"]));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches; first 20:\n{}",
        failures.len(),
        failures
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
